module secure_door (\n    input clk,\n    input rst_n,\n    input start,\n    input [3:0] N,\n    input [3:0] M,\n    input [127:0] edges,\n    output reg [3:0] result,\n    output reg done\n);\n\n    // State definitions\n    localparam [4:0] S_IDLE          = 5'd0;\n    localparam [4:0] S_INIT          = 5'd1;\n    localparam [4:0] S_FOR_EDGE      = 5'd2;\n    localparam [4:0] S_BFS_INIT      = 5'd3;\n    localparam [4:0] S_BFS_LOOP      = 5'd4;\n    localparam [4:0] S_BFS_EDGE_LOOP = 5'd5;\n    localparam [4:0] S_BFS_UPDATE    = 5'd6;\n    localparam [4:0] S_COUNT         = 5'd7;\n    localparam [4:0] S_UPDATE_MAX    = 5'd8;\n    localparam [4:0] S_NEXT_EDGE     = 5'd9;\n    localparam [4:0] S_DONE          = 5'd10;\n\n    // Registers\n    reg [4:0] state;\n    reg [3:0] edge_idx;\n    reg [8:0] visited_reg;\n    reg [3:0] max_protected;\n    reg [3:0] count_curr;\n    reg [3:0] i;\n    reg [3:0] j;\n    reg [3:0] iteration_count;\n    reg changed;\n    reg [8:0] visited_temp;\n    reg changed_temp;\n\n    // Edge extraction\n    wire [7:0] current_edge = edges[edge_idx*8 +: 8];\n    wire [3:0] current_u = current_edge[7:4];\n    wire [3:0] current_v = current_edge[3:0];\n\n    wire [7:0] edge_j = edges[j*8 +: 8];\n    wire [3:0] u_j = edge_j[7:4];\n    wire [3:0] v_j = edge_j[3:0];\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= S_IDLE;\n            done <= 1'b0;\n            result <= 4'd0;\n            edge_idx <= 4'd0;\n            visited_reg <= 9'd0;\n            max_protected <= 4'd0;\n            count_curr <= 4'd0;\n            i <= 4'd0;\n            j <= 4'd0;\n            iteration_count <= 4'd0;\n            changed <= 1'b0;\n            visited_temp <= 9'd0;\n            changed_temp <= 1'b0;\n        end else begin\n            case (state)\n                S_IDLE: begin\n                    done <= 1'b0;\n                    if (start) state <= S_INIT;\n                end\n\n                S_INIT: begin\n                    max_protected <= 4'd0;\n                    edge_idx <= 4'd0;\n                    visited_reg <= 9'd0;\n                    state <= S_FOR_EDGE;\n                end\n\n                S_FOR_EDGE: begin\n                    if (edge_idx >= M) begin\n                        state <= S_DONE;\n                    end else begin\n                        state <= S_BFS_INIT;\n                    end\n                end\n\n                S_BFS_INIT: begin\n                    visited_reg <= 9'b0_0000_1000;  // Set outside node 8 as visited\n                    iteration_count <= 4'd0;\n                    state <= S_BFS_LOOP;\n                end\n\n                S_BFS_LOOP: begin\n                    visited_temp <= visited_reg;\n                    changed_temp <= 1'b0;\n                    j <= 4'd0;\n                    state <= S_BFS_EDGE_LOOP;\n                end\n\n                S_BFS_EDGE_LOOP: begin\n                    if (j < M) begin\n                        if (j != edge_idx) begin\n                            if (visited_reg[u_j] && !visited_reg[v_j]) begin\n                                visited_temp[v_j] <= 1'b1;\n                                changed_temp <= 1'b1;\n                            end\n                            if (visited_reg[v_j] && !visited_reg[u_j]) begin\n                                visited_temp[u_j] <= 1'b1;\n                                changed_temp <= 1'b1;\n                            end\n                        end\n                        j <= j + 4'd1;\n                        state <= (j < (M - 4'd1)) ? S_BFS_EDGE_LOOP : S_BFS_UPDATE;\n                    end else begin\n                        state <= S_BFS_UPDATE;\n                    end\n                end\n\n                S_BFS_UPDATE: begin\n                    visited_reg <= visited_temp;\n                    changed <= changed_temp;\n                    iteration_count <= iteration_count + 4'd1;\n                    if (changed_temp && (iteration_count < 4'd8)) begin\n                        state <= S_BFS_LOOP;\n                    end else begin\n                        count_curr <= 4'd0;\n                        i <= 4'd0;\n                        state <= S_COUNT;\n                    end\n                end\n\n                S_COUNT: begin\n                    if (i < N) begin\n                        if (!visited_reg[i]) begin\n                            count_curr <= count_curr + 4'd1;\n                        end\n                        i <= i + 4'd1;\n                        state <= (i >= N) ? S_UPDATE_MAX : S_COUNT;\n                    end else begin\n                        state <= S_UPDATE_MAX;\n                    end\n                end\n\n                S_UPDATE_MAX: begin\n                    if (count_curr > max_protected) max_protected <= count_curr;\n                    state <= S_NEXT_EDGE;\n                end\n\n                S_NEXT_EDGE: begin\n                    edge_idx <= edge_idx + 4'd1;\n                    state <= S_FOR_EDGE;\n                end\n\n                S_DONE: begin\n                    result <= max_protected;\n                    done <= 1'b1;\n                    state <= S_IDLE;\n                end\n\n                default: state <= S_IDLE;\n            endcase\n        end\n    end\n\nendmodule